import React from 'react';
import './ZapatosCard.css'; // Importa los estilos CSS para la tarjeta si los tienes

const ZapatosCard = () => {
  return (
    <div className="zapatos-card">
      <img src={zapato.imagen} alt={zapato.nombre} className="zapatos-image" />
      <div className="zapatos-info">
        <h3 className="zapatos-name">{zapato.nombre}</h3>
        <p className="zapatos-description">{zapato.descripcion}</p>
        <p className="zapatos-price">Precio: ${zapato.precio}</p>
        <button className="zapatos-btn">Agregar al carrito</button>
      </div>
    </div>
  );
}

export default ZapatosCard;
